-- Apply ONLY to a newly created, dedicated Puna database.
-- Prices stored in integer CAD cents; no real order/payment data imported.
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,display_name VARCHAR(120) NOT NULL,role ENUM('owner','manager','staff') NOT NULL,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS products (id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT NOT NULL,price_cents INT UNSIGNED NOT NULL,kind ENUM('fresh','frozen') NOT NULL,available BOOLEAN NOT NULL DEFAULT FALSE,source_status ENUM('initial','confirmed') NOT NULL DEFAULT 'initial',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_drafts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_key VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status ENUM('draft','approved','published') NOT NULL DEFAULT 'draft',updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,screen_path VARCHAR(500) NOT NULL,category ENUM('bug','feature','question') NOT NULL,message TEXT NOT NULL,status ENUM('new','reviewing','planned','done') NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(120) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id));
